with m as (select '{"banner":"Страшилки Леса чудес уже начинаются — будьте осторожны!","image":"rotations/2026-10-26.png","teams":{"R":[{"title":"Первая половина дня · 10:00–14:00","note":"10:00–10:30 · Т — танцуем на северном входе все вместе","noteBg":"#E8B4B8","rows":[{"zone":"Веревочный лагерь","people":[{"icon":"🎃","name":"Адылов Володя","senior":true,"brks":["Ос 12:00–12:30"]},{"icon":"🦇","name":"Бражко Лёша","senior":false,"brks":["Ос 12:30–13:00"]},{"icon":"👻","name":"Бражников Саша","senior":false,"brks":["Ос 13:00–13:30"]},{"icon":"🕷️","name":"Иванкина Лера","senior":false,"brks":["Ос 13:30–14:00"]}]},{"zone":"Золото","people":[{"icon":"🧙","name":"Кочиева Майя","senior":false,"brks":["О 13:00–13:30"]}]},{"zone":"Гольф","people":[{"icon":"💀","name":"Старков Рома","senior":false,"brks":["О 12:30–13:00"]}]},{"zone":"Альфа","people":[{"icon":"🧛","name":"Митясова Оля","senior":false,"brks":[]}],"note":"Меняет обеды","steps":[["10:00–12:00","Боулинг"],["12:00–12:30","Ос"],["12:30–13:00","Гольф"],["13:00–13:30","Золото"],["13:30–14:00","Метро"]]}]},{"title":"Вторая половина дня · 14:00–18:00","note":"18:00–18:30 · общий бриф","noteBg":"#B9A7B5","rows":[{"zone":"Веревочный лагерь","people":[{"icon":"🎃","name":"Адылов Володя","senior":true,"brks":["Ос 16:00–16:30"]},{"icon":"🦇","name":"Бражко Лёша","senior":false,"brks":["Ос 16:30–17:00"]},{"icon":"💀","name":"Старков Рома","senior":false,"brks":["Ос 17:00–17:30"]},{"icon":"🧙","name":"Кочиева Майя","senior":false,"brks":["Ос 17:30–18:00"]}]},{"zone":"Золото","people":[{"icon":"🕷️","name":"Иванкина Лера","senior":false,"brks":["О 16:00–16:30"]}]},{"zone":"Гольф","people":[{"icon":"👻","name":"Бражников Саша","senior":false,"brks":["О 15:30–16:00"]}]},{"zone":"Альфа","people":[{"icon":"🧛","name":"Митясова Оля","senior":false,"brks":[]}],"note":"Меняет обеды","steps":[["14:00–15:00","Метро"],["15:00–15:30","Ос"],["15:30–16:00","Гольф"],["16:00–16:30","Золото"],["16:30–17:00","Веревочный лагерь"],["17:00–18:00","Боулинг"]]}]}],"M":[{"title":"Весь день · 10:00–18:00","note":"","noteBg":"#E8B4B8","rows":[{"zone":"Боулинг","people":[{"icon":"🔮","name":"Волкова Саша","senior":false,"brks":["О 13:30–14:30","О 17:00–18:00"]}]},{"zone":"Кино","people":[{"icon":"🍂","name":"Эльвир А.","senior":false,"brks":["О 14:30–15:00"]}]},{"zone":"VR-арена","people":[{"icon":"🕯️","name":"Зиньков В.","senior":false,"brks":[]}]},{"zone":"Няня 1","people":[{"icon":"🍁","name":"Смолянова А.","senior":false,"brks":[]}]},{"zone":"Няня 2","people":[{"icon":"🍁","name":"Смолянова А.","senior":false,"brks":["Ос 13:00–14:00"]}]},{"zone":"Детский клуб","people":[{"icon":"🍄","name":"Кристина","senior":false,"brks":["Ос 13:00–14:00"]}]}]}],"W":[{"title":"План на случай дождя","note":"","noteBg":"#7E98AE","rows":[{"zone":"Веревочный лагерь","people":[{"icon":"🎃","name":"Адылов Володя","senior":false,"brks":[]}]},{"zone":"Лучный тир","people":[{"icon":"🦇","name":"Бражко Лёша","senior":false,"brks":[]}]},{"zone":"Помощь зонтам Метро / Перекрёсток","people":[{"icon":"👻","name":"Бражников Саша","senior":false,"brks":[]}]},{"zone":"Перекрёсток: зонты","people":[{"icon":"🕷️","name":"Иванкина Лера","senior":false,"brks":[]}]},{"zone":"Золото","people":[{"icon":"🧙","name":"Кочиева Майя","senior":false,"brks":[]},{"icon":"","name":"Маргарита","senior":false,"brks":["касса"]}]},{"zone":"Зонты Метрополис","people":[{"icon":"💀","name":"Старков Рома","senior":false,"brks":[]}]}]}]},"legend":["Т — танцуем на северном входе все вместе"]}'::jsonb j)
update public.rotations r set updated_at=now(), data=
  jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(r.data,
    '{teams,R}', m.j#>'{teams,R}'),
    '{teams,M}', m.j#>'{teams,M}'),
    '{teams,W}', (select coalesce(jsonb_agg(x),'[]'::jsonb) from jsonb_array_elements(r.data#>'{teams,W}') x where x->>'title'<>'План на случай дождя') || (m.j#>'{teams,W}')),
    '{images}', coalesce(r.data->'images','{}'::jsonb) || jsonb_build_object('R','rotations/2026-10-26.png','M','rotations/2026-10-26.png')),
    '{legend}', case when r.data->'legend' @> '["Т — танцуем на северном входе все вместе"]'::jsonb then r.data->'legend' else r.data->'legend' || '["Т — танцуем на северном входе все вместе"]'::jsonb end)
from m where r.day='2026-10-26';
select day, jsonb_object_keys(data->'teams') from public.rotations where day='2026-10-26';
